import anime from "animejs";

anime({
  targets: ".box",
  translateX: 250,
  duration: 800,
  easing: "easeInOutQuad"
});

import anime from "animejs";

anime({
  targets: ".card",
  translateY: [24, 0],
  opacity: [0, 1],
  duration: 600,
  delay: anime.stagger(80),
  easing: "easeOutQuad",
});

// Line-drawing an SVG path with anime.js
anime({
  targets: "#logo path",
  strokeDashoffset: [anime.setDashoffset, 0],
  duration: 1200,
  easing: "easeInOutSine",
});

// Animate a plain object and read the value each frame
const counter = { value: 0 };

anime({
  targets: counter,
  value: 1000,
  round: 1,
  update: () => {
    element.textContent = counter.value.toLocaleString();
  },
});
